mapper.select:
SELECT O.*, CV.ConstrValDesc AS NationName
FROM shopwizard.tCatOrigin O
LEFT OUTER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cNationCode') CV ON O.NationCode = CV.ConstrVal

    AND O.OriginId = #{pOriginId}

        AND (O.OriginKorName LIKE CONCAT('%',#{pOriginName},'%') OR O.OriginEngName LIKE CONCAT('%',#{pOriginName},'%'))


ORDER BY O.${sidx} ${sord}
LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM shopwizard.tCatOrigin O LEFT OUTER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cNationCode') CV ON O.NationCode = CV.ConstrVal
AND O.OriginId = #{pOriginId}
AND (O.OriginKorName LIKE CONCAT('%',#{pOriginName},'%') OR O.OriginEngName LIKE CONCAT('%',#{pOriginName},'%'))

mapper.insert:
INSERT INTO shopwizard.tCatOrigin (
    OriginKorName, OriginEngName, OriginDesc, NationCode, State, Remark, RegistDate, RegistId, RegistName
) VALUES (
    #{originKorName}, #{originEngName}, #{originDesc}, #{nationCode}, #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE shopwizard.tCatOrigin SET
    OriginKorName = #{originKorName}, OriginEngName = #{originEngName}, OriginDesc = #{originDesc},
    NationCode = #{nationCode}, State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OriginId = #{originId}
